=== FILE: tick_timer_tb.sv ===
// Self-checking testbench for tick_timer.v (W = 16): directed checks with exact
// expected values plus a per-cycle scoreboard against a reference model of the
// register map. Exercises both modes, expiry, W1C clear, expiry-vs-clear and
// CTRL-write-vs-expiry ordering, read-only COUNT, IE gating and a mid-run reset.
`timescale 1ns / 1ps
module tick_timer_tb;
    logic        clk = 1'b0;
    logic        rst_n = 1'b0;
    logic        we = 1'b0;
    logic [1:0]  addr = 2'd0;
    logic [31:0] wdata = 32'd0;
    logic [31:0] rdata;
    logic        irq;
    int dir_checks = 0, dir_errors = 0;
    int sb_checks = 0, sb_errors = 0;
    logic        sb_on = 1'b0;
    logic [8*64-1:0] nonce;

    // Reference model state
    logic        m_en, m_mode, m_ie, m_expired;
    logic [15:0] m_load, m_count;
    wire m_wr_ctrl   = we && addr == 2'd0;
    wire m_wr_status = we && addr == 2'd3;
    wire m_expire    = m_en && m_count == 16'd0 && !m_wr_ctrl;

    tick_timer #(.W(16)) dut (.clk(clk), .rst_n(rst_n), .we(we), .addr(addr), .wdata(wdata), .rdata(rdata), .irq(irq));
    always #5 clk = ~clk;

    always @(posedge clk) begin
        if (!rst_n) begin
            m_en      <= 1'b0;
            m_mode    <= 1'b0;
            m_ie      <= 1'b0;
            m_load    <= 16'd0;
            m_count   <= 16'd0;
            m_expired <= 1'b0;
        end else begin
            m_expired <= m_expire | (m_expired & ~(m_wr_status & wdata[0]));
            if (we && addr == 2'd1)
                m_load <= wdata[15:0];
            if (m_wr_ctrl) begin
                m_en   <= wdata[0];
                m_mode <= wdata[1];
                m_ie   <= wdata[2];
                if (wdata[0] && !m_en)
                    m_count <= m_load;
            end else if (m_en) begin
                if (m_count != 16'd0)
                    m_count <= m_count - 16'd1;
                else if (m_mode)
                    m_count <= m_load;
                else
                    m_en <= 1'b0;
            end
        end
    end

    function automatic logic [31:0] model_rdata(input logic [1:0] a);
        case (a)
            2'd0:    model_rdata = {29'd0, m_ie, m_mode, m_en};
            2'd1:    model_rdata = {16'd0, m_load};
            2'd2:    model_rdata = {16'd0, m_count};
            default: model_rdata = {31'd0, m_expired};
        endcase
    endfunction

    always @(negedge clk) begin
        if (sb_on) begin
            sb_checks++;
            if (rdata !== model_rdata(addr) || irq !== (m_expired & m_ie)) begin
                sb_errors++;
                $display("SCOREBOARD MISMATCH at %0t: addr %0d rdata %h expected %h irq %b expected %b",
                         $time, addr, rdata, model_rdata(addr), irq, m_expired & m_ie);
            end
        end
    end

    task automatic expect_reg(input logic [1:0] a, input logic [31:0] expected);
        addr = a;
        #1;
        dir_checks++;
        if (rdata !== expected) begin
            dir_errors++;
            $display("CHECK FAILED at %0t: reg %0d read %h expected %h", $time, a, rdata, expected);
        end
    endtask

    task automatic expect_irq(input logic expected);
        dir_checks++;
        if (irq !== expected) begin
            dir_errors++;
            $display("CHECK FAILED at %0t: irq %b expected %b", $time, irq, expected);
        end
    endtask

    task automatic write(input logic [1:0] a, input logic [31:0] d);
        we = 1'b1; addr = a; wdata = d;
        @(posedge clk); #1;
        we = 1'b0; wdata = 32'd0;
    endtask

    task automatic next_cycle();
        @(posedge clk); #1;
    endtask

    initial begin
        repeat (3) @(posedge clk);
        #1;
        rst_n = 1'b1;
        next_cycle();
        sb_on = 1'b1;

        // Reset values
        expect_reg(2'd0, 32'd0); expect_reg(2'd1, 32'd0); expect_reg(2'd2, 32'd0); expect_reg(2'd3, 32'd0);
        expect_irq(1'b0);

        // Register access, upper wdata bits ignored, all wdata bits toggled
        write(2'd1, 32'hFFFF_FFFF); expect_reg(2'd1, 32'h0000_FFFF); expect_reg(2'd2, 32'd0);
        write(2'd1, 32'h0000_0000); expect_reg(2'd1, 32'd0);
        write(2'd1, 32'hAAAA_5555); expect_reg(2'd1, 32'h0000_5555);
        write(2'd1, 32'h5555_AAAA); expect_reg(2'd1, 32'h0000_AAAA);
        write(2'd0, 32'hFFFF_FFF8); expect_reg(2'd0, 32'd0);
        write(2'd0, 32'h0000_0006); expect_reg(2'd0, 32'h6); expect_reg(2'd2, 32'd0); expect_reg(2'd3, 32'd0);
        expect_irq(1'b0);
        next_cycle(); expect_reg(2'd2, 32'd0); expect_reg(2'd3, 32'd0);
        write(2'd0, 32'd0); expect_reg(2'd0, 32'd0);
        write(2'd2, 32'hFFFF_FFFF); expect_reg(2'd2, 32'd0);   // COUNT is read-only
        write(2'd3, 32'h1); expect_reg(2'd3, 32'd0);           // clear with nothing expired

        // One-shot: LOAD 3, EN + IE
        write(2'd1, 32'd3); write(2'd0, 32'h5);
        expect_reg(2'd2, 32'd3); expect_reg(2'd0, 32'h5); expect_reg(2'd3, 32'd0);
        next_cycle(); expect_reg(2'd2, 32'd2);
        next_cycle(); expect_reg(2'd2, 32'd1);
        next_cycle(); expect_reg(2'd2, 32'd0); expect_reg(2'd3, 32'd0); expect_irq(1'b0);
        next_cycle(); expect_reg(2'd3, 32'd1); expect_irq(1'b1); expect_reg(2'd0, 32'h4); expect_reg(2'd2, 32'd0);
        next_cycle(); next_cycle(); expect_reg(2'd3, 32'd1); expect_reg(2'd2, 32'd0);
        write(2'd3, 32'h0); expect_reg(2'd3, 32'd1);
        write(2'd3, 32'hFFFF_FFFE); expect_reg(2'd3, 32'd1); expect_irq(1'b1);
        write(2'd3, 32'h1); expect_reg(2'd3, 32'd0); expect_irq(1'b0);

        // Periodic: LOAD 2, EN + MODE, IE off
        write(2'd1, 32'd2); write(2'd0, 32'h3);
        expect_reg(2'd2, 32'd2); expect_reg(2'd0, 32'h3);
        next_cycle(); expect_reg(2'd2, 32'd1);
        next_cycle(); expect_reg(2'd2, 32'd0); expect_reg(2'd3, 32'd0);
        next_cycle(); expect_reg(2'd2, 32'd2); expect_reg(2'd3, 32'd1); expect_irq(1'b0);
        next_cycle(); expect_reg(2'd2, 32'd1);
        next_cycle(); expect_reg(2'd2, 32'd0);
        write(2'd3, 32'h1); expect_reg(2'd3, 32'd1); expect_reg(2'd2, 32'd2);   // expiry wins over clear
        write(2'd3, 32'h1); expect_reg(2'd3, 32'd0); expect_reg(2'd2, 32'd1);
        write(2'd0, 32'h7); expect_reg(2'd0, 32'h7); expect_reg(2'd2, 32'd1);   // CTRL write holds count, no reload
        next_cycle(); expect_reg(2'd2, 32'd0); expect_reg(2'd3, 32'd0);
        next_cycle(); expect_reg(2'd3, 32'd1); expect_irq(1'b1); expect_reg(2'd2, 32'd2);
        write(2'd3, 32'h1); expect_reg(2'd3, 32'd0); expect_irq(1'b0); expect_reg(2'd2, 32'd1);
        next_cycle(); expect_reg(2'd2, 32'd0);
        write(2'd0, 32'h7); expect_reg(2'd3, 32'd0); expect_reg(2'd2, 32'd0);   // CTRL write takes the expiry edge
        next_cycle(); expect_reg(2'd3, 32'd1); expect_irq(1'b1); expect_reg(2'd2, 32'd2);
        write(2'd0, 32'h0); expect_reg(2'd0, 32'd0); expect_reg(2'd2, 32'd2); expect_reg(2'd3, 32'd1);
        expect_irq(1'b0);
        next_cycle(); next_cycle(); expect_reg(2'd2, 32'd2); expect_reg(2'd3, 32'd1);
        write(2'd3, 32'h1); expect_reg(2'd3, 32'd0);

        // Count bit toggles: 0x8000 -> 0x7FFF -> 0x7FFE, stop, restart from 0
        write(2'd1, 32'h0000_8000); write(2'd0, 32'h1);
        expect_reg(2'd2, 32'h8000);
        next_cycle(); expect_reg(2'd2, 32'h7FFF);
        next_cycle(); expect_reg(2'd2, 32'h7FFE);
        write(2'd0, 32'h0); expect_reg(2'd2, 32'h7FFE); expect_reg(2'd0, 32'd0);
        write(2'd1, 32'h0); write(2'd0, 32'h1);
        expect_reg(2'd2, 32'd0); expect_reg(2'd3, 32'd0); expect_reg(2'd0, 32'h1);
        next_cycle(); expect_reg(2'd3, 32'd1); expect_reg(2'd0, 32'd0); expect_irq(1'b0);
        write(2'd3, 32'h1); expect_reg(2'd3, 32'd0);

        // Reset while running and expired
        write(2'd1, 32'd1); write(2'd0, 32'h7);
        expect_reg(2'd2, 32'd1);
        next_cycle(); expect_reg(2'd2, 32'd0);
        next_cycle(); expect_reg(2'd3, 32'd1); expect_irq(1'b1); expect_reg(2'd2, 32'd1);
        rst_n = 1'b0;
        next_cycle();
        rst_n = 1'b1;
        expect_reg(2'd0, 32'd0); expect_reg(2'd1, 32'd0); expect_reg(2'd2, 32'd0); expect_reg(2'd3, 32'd0);
        expect_irq(1'b0);
        next_cycle(); expect_reg(2'd2, 32'd0); expect_reg(2'd3, 32'd0);
        next_cycle();

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce,
                 (dir_checks - dir_errors) + (sb_checks - sb_errors), dir_errors + sb_errors);
        $finish;
    end
endmodule
=== END FILE ===
